retained_functions.npos:
def npos(f):
    for n in f.segmentation['nodes']:
        if n['color']=='N': return n['boundary'][0], n['pixels']
    return None

retained_functions.barlen:
def barlen(f):
    row = f.ascii.split('\n')[63]
    return row.count('W'), row[0], row[-1]

retained_functions.summarize:
def summarize(d):
    out=[]
    for k in ['moved','rotated','appeared','disappeared','changed_color','resized']:
        for e in (d.get(k) or []):
            out.append((k, {kk:e[kk] for kk in e if kk in ('at','at_before','at_after','pixels','color','before_color','after_color','rotated_by','bbox')}))
    return out

retained_functions.region_hash:
def region_hash(f, r0,r1,c0,c1):
    a=f.ascii.split('\n')
    return hash('\n'.join(a[r][c0:c1+1] for r in range(r0,r1+1)))

retained_functions.arm_pose:
def arm_pose(f):
    for n in f.segmentation['nodes']:
        if n['color']=='R' and 20<=n['pixels']<=30: return n['boundary'][0], n['pixels']
    return None

retained_functions.blue_slot:
def blue_slot(f):
    for n in f.segmentation['nodes']:
        if n['color']=='b' and n['pixels']==16: return n['boundary'][0]
    return None

